export const makeScene = (S, M) => {
  const D2R = M.D2R, ring = (r, a, y) => [r * Math.cos(a * D2R), y, -r * Math.sin(a * D2R)];
  const CY = -3.1;                                   // 光室中心高度
  const A_LED = 210, A_PD = 330, A_WALL = 270;       // 发射管、接收管、挡光墙所在方位（度）
  const THRESH = 0.15;                               // dB/m（示意）

  // —— 烟浓度模型：随时间上升，过阈值后连续确认 3 次才报警 ——
  const rise = (u) => Math.min(0.32, THRESH * Math.pow(Math.max(0, u - 0.18) / 0.4, 1.3));     // 0.58 时正好到阈值
  const smoke = (u) => (u < 0.84 ? rise(u) : rise(0.84) * (1 - M.smooth(0.84, 0.88, u)));
  const tCross = (() => { let lo = 0.16, hi = 0.84; for (let i = 0; i < 40; i++) { const m = (lo + hi) / 2; if (smoke(m) < THRESH) lo = m; else hi = m; } return hi; })();
  const SAMPLE = 0.027;                              // 两次采样之间的循环进度
  const tAlarm = tCross + 3 * SAMPLE;
  const state = (u) => {
    if (u >= 0.84) return u < 0.9 ? '自检：按下测试键' : '待机';
    if (u >= tAlarm) return '火警！';
    if (u >= tCross) return `超阈值，确认 ${Math.min(3, 1 + Math.floor((u - tCross) / SAMPLE))}/3`;
    return smoke(u) > 0.01 ? '检测中' : '待机';
  };
  const signal = (u) => 0.02 + 6 * smoke(u);        // 光电管收到的散射光（相对值）

  // —— 形状 ——
  const shellMesh = S.lathe([[0, -4.6], [3.0, -4.6], [4.4, -4.35], [5.2, -3.8], [5.5, -3.0], [5.5, -0.6], [0, -0.6]], { seg: 44 });
  const vents = S.merge(...Array.from({ length: 18 }, (_, i) => { const a = i * 20 + 10; return S.xf(S.box(0.95, 1.3, 0.14), { at: ring(5.56, a, -2.2), rot: [0, a + 90, 0] }); }));
  const baffles = S.merge(
    ...Array.from({ length: 14 }, (_, i) => { const a = i * (360 / 14); return S.xf(S.box(0.95, 1.45, 0.1), { at: ring(1.85, a, CY), rot: [0, a + 90 + 38, 0] }); }),
    S.xf(S.box(1.35, 1.3, 0.12), { at: ring(1.02, A_WALL, CY), rot: [0, A_WALL, 0] }),            // “7”字挡光墙
    S.xf(S.box(0.12, 1.3, 0.5), { at: ring(0.38, A_WALL, CY), rot: [0, A_WALL, 0] })
  );
  const caps = S.merge(S.xf(S.cyl(2.25, 0.12, { seg: 32 }), { at: [0, CY + 0.78, 0] }), S.xf(S.cyl(2.25, 0.12, { seg: 32 }), { at: [0, CY - 0.78, 0] }));
  const diode = (col) => S.merge(S.xf(S.cyl(0.22, 0.7, { axis: 'x', seg: 12 }), { at: [0.35, 0, 0] }), S.xf(S.sphere(0.22, { seg: 10 }), { at: [0, 0, 0] }), S.xf(S.cyl(0.04, 0.9, { axis: 'x', seg: 5 }), { at: [1.1, 0.08, 0] }));
  const wave = () => S.torus(1, 0.05, { seg: 40, tseg: 5 });

  const ledTip = ring(1.1, A_LED, CY), pdTip = ring(1.1, A_PD, CY);
  return {
    fig: '图 4',
    title: '烟雾报警器怎么“看见”烟',
    autoplay: false, sway: false,
    subtitle: '用户提供的教学示意 · 内部结构与参数未经实物核验',
    view: { yaw: -28, pitch: -38, zoom: 1.05 }, labels: 'step',
    xray: true, ground: false, cycle: 36,
    hint: '拖动旋转 · 点部件看说明 · X 切换透视',
    parts: [
      { id: 'ceiling', role: 'ground', mesh: S.cyl(8.5, 0.5, { seg: 48 }), at: [0, 0.25, 0], color: '#f7f3ea', hatch: false, pick: false, dim: false, name: '天花板' },
      { id: 'base', mesh: S.cyl(5.0, 0.6, { seg: 40 }), at: [0, -0.3, 0], color: 'gray', label: '安装底座', anchor: [-4.6, 0, 1.6], note: "示意中的安装底座；实际安装位置与方式应按产品说明。" },
      { id: 'cover', role: 'shell', mesh: shellMesh, color: '#dfe7ef', label: '外壳', anchor: [-5.2, -3.6, 1.5], note: "透视查看简化布局，不代表真实型号的内部结构。" },
      { id: 'vents', mesh: vents, color: 'slate', label: '进烟口', anchor: ring(5.6, 150, -2.2), note: "示意中的进烟开口与烟流路径。" },
      { id: 'pcb', role: 'inside', in: 'cover', mesh: S.cyl(4.9, 0.16, { seg: 40 }), at: [0, -1.1, 0], color: '#3ddc97', label: '电路板', anchor: [3.6, 0, -2.6], note: "示意中的光电信号与电路板。" },
      { id: 'mcu', role: 'inside', in: 'cover', mesh: S.box(1.3, 0.25, 1.3), at: [1.9, -1.32, 1.3], color: 'slate', label: '单片机', note: "动画采用简化阈值判断；不表示真实设备不会误报或漏报。" },
      { id: 'battery', role: 'inside', in: 'cover', mesh: S.merge(S.cyl(0.85, 3.4, { axis: 'x', seg: 18 }), S.xf(S.cyl(0.3, 0.2, { axis: 'x', seg: 10 }), { at: [1.8, 0, 0] })), at: [-2.3, -2.0, 1.9], color: 'orange', label: '电池', note: "示意中的电池。自检与更换要求未核验。" },
      { id: 'horn', role: 'inside', in: 'cover', mesh: S.merge(S.cyl(1.9, 0.22, { seg: 32 }), S.xf(S.cyl(1.25, 0.12, { seg: 28 }), { at: [0, -0.15, 0] })), at: [2.3, -1.5, -1.9], color: '#d4a373', label: '蜂鸣片', note: "示意中的蜂鸣片，动画不测试实际报警声。" },
      { id: 'maze', role: 'inside', in: 'cover', mesh: baffles, color: '#4a4f5c', label: '迷宫光室', anchor: ring(2.0, 100, CY + 0.4), note: "示意中的光室挡片与散射路径，非经过校准的光学模型。" },
      { id: 'caps', role: 'inside', in: 'cover', mesh: caps, color: '#4a4f5c', glass: true, pick: false, name: '光室上下盖' },
      { id: 'ledIR', role: 'inside', in: 'cover', mesh: diode(), at: ring(1.1, A_LED, CY), rot: [0, A_LED, 0], color: '#ff8fab', label: '红外发射管', anchor: [0.4, 0.2, 0], note: "示意中的红外发射管。闪烁周期为动画设定。" },
      { id: 'pd', role: 'inside', in: 'cover', mesh: diode(), at: ring(1.1, A_PD, CY), rot: [0, A_PD, 0], color: '#7c4dff', label: '光电接收管', anchor: [0.4, 0.2, 0], note: "示意中的接收管位置，角度和信号为动画设定。" },
      { id: 'button', mesh: S.merge(S.cyl(1.1, 0.35, { seg: 28 }), S.xf(S.cyl(0.7, 0.05, { seg: 20 }), { at: [0, -0.2, 0] })), at: [0, -4.75, 0], color: '#ffd166', glass: true, label: '测试/消音键', anchor: [1.1, -0.1, 0], note: "示意中的测试键。真实测试、消音与处置方法应按产品说明。" },
      { id: 'ledR', mesh: S.sphere(0.24, { seg: 10 }), at: [-0.45, -4.66, -2.0], color: '#ff3b3b', glow: 'active', label: '红色报警灯', note: "示意中的红色指示灯；可见性和报警效果未核验。" },
      { id: 'ledY', mesh: S.sphere(0.24, { seg: 10 }), at: [0.45, -4.66, -2.0], color: '#ffd166', glow: 'active', label: '黄色故障灯', note: "示意中的故障指示灯；真实故障逻辑未核验。" },
      ...[0, 1, 2].map((i) => ({ id: 'wave' + i, mesh: wave(), at: [0, -5.4, 0], color: '#ff6b6b', fit: false, pick: false, dim: false, hatch: false, opacity: 0 }))
    ],
    flows: [
      { id: 'rise', role: 'part', color: '#a7adb4', count: 46, speed: 1.2, size: 0.22, spread: 0.8, path: [[-13, -13, 4], [-12, -8, 3], [-10.5, -3, 2], [-9, -1, 1.2], [-7, -1.7, 0.5], [-5.7, -2.2, 0.2]] },
      { id: 'enter', in: 'cover', color: '#8d939b', count: 28, speed: 1.4, size: 0.2, spread: 0.18, path: [[-5.6, -2.2, 0.2], [-4.4, -2.7, 0.4], [-3.1, -3.0, 0.1], [-1.9, CY, -0.3], [-0.6, CY, 0.4], [0.5, CY, -0.2], [0.1, CY + 0.2, 0.5]] },
      { id: 'ir', in: 'cover', color: '#ff3b3b', count: 9, speed: 7, size: 0.16, path: [ledTip, ring(1.62, A_LED + 180, CY)] },
      { id: 'scatter', in: 'cover', color: '#ff9f1c', count: 8, speed: 5, size: 0.16, path: [[0.05, CY, 0.05], pdTip] },
      { id: 'signal', in: 'cover', color: '#9be15d', count: 10, speed: 4, size: 0.12, path: [ring(1.6, A_PD, CY), ring(2.6, A_PD + 8, -2.2), [1.9, -1.45, 1.3]] },
      { id: 'beep', in: 'cover', color: '#9be15d', count: 10, speed: 4, size: 0.12, path: [[1.9, -1.45, 1.3], [2.3, -1.45, 0], [2.3, -1.6, -1.9]] }
    ],
    steps: [
      { name: '待机', from: 0, to: 0.16, color: '#ff5d5d', active: ['ledIR', 'pd', 'maze'], flows: ['ir'], view: { zoom: 2.3, pitch: -58 },
        text: "观察简化的发射管与接收管布局。光路是教学示意。" },
      { name: '烟往上走', from: 0.16, to: 0.33, color: '#8d939b', active: ['vents', 'maze', 'base'], flows: ['rise', 'enter'], view: { zoom: 0.95, pitch: -20 },
        text: "观察烟流进入光室的动画，不作为安装位置指导。" },
      { name: '光被烟散射', from: 0.33, to: 0.5, color: '#ffb347', active: ['ledIR', 'pd', 'maze'], flows: ['ir', 'scatter', 'enter'], view: { zoom: 2.5, pitch: -62 },
        text: "观察散射光到达接收管的示意路径，角度与信号未经测量。" },
      { name: '判定火警', from: 0.5, to: 0.66, color: '#9be15d', active: ['pd', 'pcb', 'mcu'], flows: ['ir', 'scatter', 'signal'], view: { zoom: 1.5, pitch: -48 },
        text: "动画使用简化的多次采样阈值判断，不代表真实设备的报警条件或误报性能。" },
      { name: '报警', from: 0.66, to: 0.84, color: '#ff3b3b', active: ['horn', 'ledR', 'mcu'], flows: ['beep'], view: { zoom: 0.95, pitch: -26 },
        text: "观察蜂鸣片与红灯同时高亮。没有测试实际声压、灵敏度或消音功能。" },
      { name: '自检与电池', from: 0.84, to: 1, color: '#ffd166', active: ['button', 'battery', 'ledY', 'horn'], view: { zoom: 1.4, pitch: -50 },
        text: "观察电池、测试键和故障灯的关联；真实自检、测试及更换要求依产品说明。" }
    ],
    animate(u, api) {
      const alarm = u >= tAlarm && u < 0.84, test = u >= 0.85 && u < 0.89;
      for (let i = 0; i < 3; i++) {
        const ph = M.frac(api.t * 0.9 + i / 3), on = alarm ? 1 : test ? 0.6 : 0;
        api.set('wave' + i, { scale: [2 + 7 * ph, 1, 2 + 7 * ph], pos: [0, -0.6 * ph, 0], opacity: on * (1 - ph) * 0.9, visible: on > 0 });
      }
      api.set('button', { pos: [0, test ? 0.16 : 0, 0] });
      api.set('ledR', { scale: alarm && M.frac(api.t * 1.5) < 0.5 ? 1.25 : 1 });
      api.flow('enter', u > 0.18 && u < 0.84 ? 1 : 0);
      api.flow('rise', u > 0.16 && u < 0.84 ? 1 : 0);
      api.flow('scatter', u > 0.33 && u < 0.84 ? M.clamp(smoke(u) / THRESH) : 0);
    },
    readout(u) {
      return `烟 ${smoke(u).toFixed(2)} dB/m · 散射光 ${signal(u).toFixed(2)} · 阈值 ${THRESH} · ${state(u)}`;
    },
    caption: '所有尺寸、温度、阈值和读数均为动画算例；标准适用性、实际功能与安全效果尚未核验。'
  };
};

